/**
 * Types for what the MACH product engine (studio.py) returns, in one place.
 *
 * Derived from the real engine output in web/fixtures/*.json (generated by web/fixtures/generate.py)
 * and from the emit() calls in skills/product-studio/scripts/studio.py and handoff.py. When the
 * engine changes, regenerate the fixtures and update this file. The showcase loads every fixture
 * through `fixture<T>()` (apps/showcase/src/fixtures.ts), which checks each file's field names and
 * nesting against these types at compile time, so a renamed or missing field fails the build.
 * Enumerated values (a new status word) are not caught that way: JSON imports widen them to string.
 * Fields the engine still reports but no screen reads are left out.
 *
 * These types describe; they never decide. Product rules live only in the engine.
 */

import type {
  BriefCheck,
  BriefShow,
  CaseCheck,
  CaseShow,
  IdeaAdded,
  IdeaBoard,
  IdeaChain,
  IdeaChanged,
  IdeaFaults,
  IdeaLookupsInput,
  IdeaLookupsResult,
  IdeaPublished,
  IdeaRenumbered,
  IdeaShow,
  IdeaSized,
  IdeaStageResult,
  LookbackRecorded,
  RefreshIdeas,
  Serves,
  ShapeApplied,
  ShapeMapInput,
  ShapeMapRecorded,
  ShapeMapStatus,
  ShapeSettled,
  SliceFromIdea,
  StatusIdeas,
  VerdictRecorded,
} from "./shape";
import type {
  DesignImport,
  DesignPublished,
  DesignSettled,
  DesignSettleAs,
  DesignShow,
  DesignSummary,
  NeedChanged,
  NeedKind,
  NeedList,
  NeedNothingToSay,
  NeedsBlock,
  NeedsPublishResult,
  ReconcileNeeds,
} from "./needs";

/* ── Vocabulary ─────────────────────────────────────────────────────────── */

export type ProjectStatus = "draft" | "active" | "archived";
/** An epic is a container for slices: in the project (open), or set aside (deferred). It is never approved. */
export type EpicStatus = "open" | "deferred";
export type SliceStatus = "draft" | "interviewing" | "ready_for_approval" | "approved_for_engineering" | "superseded";

export type RiskTier = "Low" | "Medium" | "High";

/**
 * Where a slice is with the builders, as the engine read it from its GitHub issue at the last
 * refresh: the issue's state label. Null when the engine has not read one.
 */
export type SliceStateLabel = "mach:ready" | "mach:building" | "mach:question" | "mach:shipped";

/* ── Artifacts (the bytes the engine writes) ────────────────────────────── */

export interface Project {
  schema_version?: number;
  project_id: string;
  name: string;
  status: ProjectStatus;
  revision: number;
  vision: string;
  outcomes: string[];
}

export interface Epic {
  schema_version: number;
  epic_id: string;
  project_id: string;
  revision: number;
  title: string;
  status: EpicStatus;
  acceptance_criteria: string[];
  /** The Jira issue the epic belongs to (M13 E), set with `epic.link`. Absent when there is none. */
  tracking?: Tracking;
  /** M16: the idea and outcomes an epic made by Shape's apply serves; identifiers only. */
  serves?: Serves;
}

export interface WorkOrder {
  schema_version: number;
  slice_id: string;
  project_id: string;
  epic_id: string;
  revision: number;
  title: string;
  status: SliceStatus;
  dependencies: string[];
  open_questions: string[];
  spec_path: string | null;
  spec_sha256: string | null;
  /** The slice's own Jira key (M13 E); without it the slice is handed over with its epic's. */
  tracking?: Tracking;
  /** Design mocks bound to the slice (M14 C), in SHA-256 order. Absent when there are none. */
  mocks?: DesignMock[];
  /** The PRD the slice was made from (M13 D): identifiers and line numbers only. */
  source?: PrdSource;
  /** The request the slice was started from (M8): identifiers only, never issue text. */
  origin?: { kind: "github_issue" | (string & {}); repository: string; number: number };
  /** M16: the idea and outcomes a slice made by Shape's apply serves; its why must name them (`idea.why_line`). */
  serves?: Serves;
}

/* ── Operation results ──────────────────────────────────────────────────── */

export interface Where {
  project: string;
  workspace: string;
  specs_dir: string;
  interview_method: string;
  slice_template: string;
  spec_rules: string[];
  intent_template: string;
  is_git_repository: boolean;
}

/**
 * One slice's place outside the workspace (`slices[].github` in status and slice show), from the
 * engine's record alone: where it was saved, its issue, and what the last refresh read there.
 */
export interface SliceGithub {
  /** "github" once saving finished there, "folder" when it was written to the ready folder, else null. */
  saved: "github" | "folder" | null;
  /** Marking it ready stopped part way; marking it ready again finishes. */
  unfinished: boolean;
  issue: number | null;
  /** The issue's address, as the engine gives it. */
  url: string | null;
  state_label: SliceStateLabel | null;
  /** The approved version saved on GitHub. */
  revision: number | null;
  /** Someone changed the issue after it was approved, so the builders will not take it. */
  changed_on_github: boolean;
  /** Someone else saved a newer version; the PM chooses theirs or keeps their own. */
  newer_elsewhere: boolean;
  /** Another slice on GitHub already uses this draft's number. */
  number_taken: boolean;
  /** The builders' question, written by them on the slice's issue: data, shown as their words. */
  question: string | null;
  /** The engine's sentence saying whose words the question is. */
  question_note: string | null;
  /** Earlier issues of this slice that have shipped. */
  shipped_issues: number[];
  /** When this version was marked ready, taken by the builders, asked about and shipped (ISO 8601, UTC); null when not known. */
  times: { marked_ready: string | null; building: string | null; question: string | null; shipped: string | null };
  /** One word for where the slice is: its draft's state until approved, then where it is with the builders. */
  progress: SliceProgress | null;
}

export type SliceProgress =
  | "draft"
  | "interviewing"
  | "ready_for_approval"
  | "approved"
  | "ready_to_build"
  | "being_built"
  | "question"
  | "shipped"
  | "superseded";

/** An epic's slices by place (`epics[].counts`), and how many are ready or further, with what that means in words. */
export interface EpicCounts {
  total: number;
  by_progress: Partial<Record<SliceProgress, number>>;
  ready_or_further: number;
  ready_or_further_means: string;
}

/** `status.saved`: whether everything has reached where it is kept, and each thing that has not, in the engine's words. */
export interface SavedReport {
  everything_saved: boolean;
  note: string;
  /** M15: unpublished product principles are listed too (principles_unpublished, or principles_unfinished when publishing stopped part way). */
  not_saved: Array<{
    kind:
      | "unfinished"
      | "changed_since_ready"
      | "refresh_failed"
      | "request_updates"
      | "principles_unpublished"
      | "principles_unfinished"
      /** M16: an idea whose save to GitHub stopped part way, or that changed since it was saved there. */
      | "idea_unfinished"
      | "idea_changed"
      /** M17: technical needs not published, or a publish that stopped part way. */
      | "needs_unpublished"
      | "needs_unfinished"
      | (string & {});
    target: string | null;
    text: string;
  }>;
}

export interface StatusEpicRow {
  epic_id: string;
  title: string;
  status: EpicStatus;
  revision: number;
  acceptance_criteria: string[];
  /** The epic's issue on GitHub, once a slice under it was saved there, and its address. */
  issue: number | null;
  url: string | null;
  counts: EpicCounts;
  /** M15: the epic's own Jira key; absent when it has none. */
  tracking?: Tracking;
}

export interface StatusSliceRow {
  slice_id: string;
  title: string;
  epic_id: string;
  status: SliceStatus;
  revision: number;
  /** A count here (status); a list on the work order. */
  open_questions: number;
  spec: string | null;
  has_intent: boolean;
  resume_note: string | null;
  /** The slices this one needs first. */
  dependencies: string[];
  /** Whether the spec and why may be edited now. */
  editable: boolean;
  github: SliceGithub;
  /** M13 A: present when the project has principles and the slice has a spec. */
  principles?: SlicePrinciplesFlag;
  /** M13 B: present only when a row of the spec's effects now names a rule no longer in force. */
  shipped_moved?: ShippedMoved;
  /** M15: one line saying a policy pack this slice's spec answered has changed since; absent otherwise. */
  policies_changed?: string;
  /** M15: the slice's own Jira key; absent when it has none (its epic's key is on the epic's row). */
  tracking?: Tracking;
}

/** An approval the engine withdrew, and why, in the PM's words (status.approvals_withdrawn). */
export interface ApprovalWithdrawn {
  /** SLICE-001. */
  artifact: string;
  kind: "slice" | (string & {});
  reason: string | null;
  /** ISO 8601. */
  at: string | null;
}

export interface Status {
  project: (Omit<Project, "schema_version"> & { issue: number | null; url: string | null }) | null;
  /** Approvals the engine withdrew (a reopen, a renumber, a version taken from GitHub), with the reason. */
  approvals_withdrawn: ApprovalWithdrawn[];
  epics: StatusEpicRow[];
  slices: StatusSliceRow[];
  /** The GitHub repository the project's issues live in, and when they were last read. */
  github: { repository: string | null; form: "sub_issues" | "task_list" | null; last_read: string | null };
  current_slice: string | null;
  last_refreshed: string | null;
  saved: SavedReport;
  /** Each epic's order of its slices. */
  order: OrderRow[];
  /** Updates to requests' issues not made yet, in plain words. Absent when there are none. */
  github_updates_note?: string;
  github_updates_not_made_note?: string;
  structurally_valid: boolean | null;
  structural_errors: string[];
  factory_authorized: false;
  /** The engine's suggestions as sentences (the terminal skill's form). The app shows `next_actions`. */
  suggested_next: string[];
  /** What to do next, in order, structured. */
  next_actions: NextAction[];
  /** M13 A: the principles block. Present once the project exists. Its `next` is the sentence the app shows (no next_actions kind). */
  principles?: PrinciplesBlock;
  /** M13 D: one summary row per imported PRD; absent when none was imported. */
  prds?: PrdSummary[];
  /** M16: Shape's board, with each idea's next step. Absent when the workspace has no idea. */
  ideas?: StatusIdeas;
  /** M17: the technical needs. Absent for a project that never opened them (no needs file, nothing published). */
  needs?: NeedsBlock;
  /** M17: the brought-in designs, one summary each. Absent when none was brought in. */
  designs?: DesignSummary[];
}

/**
 * One recommended next step, as the engine reports it in `status.next_actions`.
 * `target` is the artifact it concerns: an ID (SLICE-002, EPIC-001), or null.
 */
export interface NextAction {
  kind: NextActionKind;
  target: string | null;
  title: string;
  reason: string | null;
  /** Other artifacts the action concerns. */
  related?: string[];
}

/**
 * A refusal's structured suggestion: the app action that would resolve it (error.hint). The
 * vocabulary is the next-action kinds plus the acts that resolve a refusal.
 */
export interface ErrorHint {
  kind: HintKind;
  /** The artifact to act on: SLICE-001, EPIC-001, or null for the project. */
  target: string | null;
}

export type HintKind =
  | NextActionKind
  | "reopen_slice"
  | "renumber_epic"
  | "edit_project"
  /** POST /api/interview for a slice this host already interviews: `target` is the live interview's ID. */
  | "open_interview";

/** The engine's NEXT_ACTION_KINDS. Unknown kinds are still shown, routed by their target. */
export type NextActionKind =
  | "define_project"
  | "add_epic"
  | "start_slice"
  | "continue_interview"
  | "answer_question"
  | "mark_ready"
  | "finish_ready"
  | "reconcile"
  | "renumber_slice"
  | (string & {});

export interface Validate {
  counts: { epics: number; slices: number };
  errors: string[];
  factory_authorized: false;
  project_id: string;
  valid: boolean;
  validation_scope: string;
}

/** One slice issue as the last refresh read it. Its title was written on GitHub: show it as plain text. */
export interface OnGithubIssue {
  issue: number;
  state: "open" | "closed" | (string & {});
  state_label: SliceStateLabel | null;
  revision: number;
  title: string | null;
  /** Null when the issue's comments could not be read. */
  matches_approval: boolean | null;
  /** The GitHub account that approved this version. */
  approved_by: string | null;
  /** The builders' question on this issue, their words; null when there is none. */
  question: string | null;
}

/** `refresh.github.slices[]`: every slice the workspace or GitHub knows. */
export interface RefreshGithubSlice extends SliceGithub {
  slice_id: string;
  in_workspace: boolean;
  on_github: OnGithubIssue[];
  title: string | null;
}

export interface RefreshGithub {
  repository: string | null;
  refreshed: boolean;
  /** Why GitHub could not be read, in plain words. */
  problem: string | null;
  refreshed_at: string | null;
  form: "sub_issues" | "task_list" | null;
  project_issue: number | null;
  project_url: string | null;
  epics: Record<string, number>;
  epic_urls: Record<string, string>;
  slices: RefreshGithubSlice[];
  order: OrderRow[];
  /** M13 A: where the principles are published, as this refresh read them. */
  principles?: PrinciplesPublished;
  /** M17: where the technical needs are published, as this refresh read them (the same shape). */
  needs?: PrinciplesPublished;
}

export interface Refresh {
  /** Whether GitHub was read. */
  refreshed: boolean;
  /** Why GitHub could not be read, in plain words, when refreshed is false. */
  problem: string | null;
  github: RefreshGithub;
  factory_authorized: false;
  /** M13 B: slices whose effects now name a rule no longer in force, by slice. Absent when none. */
  shipped_moved?: Record<string, ShippedMoved>;
  /** M13 A: another product manager's newer principles, taken because nothing here was unpublished. */
  principles_taken?: { revision: number; approved_by?: string | null; [key: string]: unknown };
  /** M16: the idea issues read back (read only); absent when Shape was never used here. */
  ideas?: RefreshIdeas;
  /** M17: another product manager's newer technical needs, taken because nothing here was unpublished. */
  needs_taken?: { revision: number; note: string };
}

export interface SpecCounts {
  invariants: number;
  functional_requirements: number;
  matrix_rules: number;
  scenarios: number;
}

/**
 * One finding of the engine's check, placed by the spec's own section heading ("Invariants",
 * "Acceptance criteria"...). `section` null means it is about the whole specification.
 */
export interface CheckDiagnostic {
  severity: "error" | "warning" | (string & {});
  rule: string | null;
  line: number | null;
  section: string | null;
  message: string;
}

export interface SliceCheck {
  slice_id: string;
  spec: string | null;
  errors: string[];
  warnings: string[];
  /** The errors and warnings with their section. */
  diagnostics?: CheckDiagnostic[];
  open_questions: string[];
  intent_problems: string[];
  /** M13 D: for a slice made from a PRD, drafted answers not settled and a why that does not name the PRD. Empty otherwise. */
  prd_problems?: string[];
  /** M16: for a slice made from an idea, a why that does not name the idea and outcomes it serves. Absent otherwise. */
  serves_problems?: string[];
  /** M13 B: the shipped rules the spec was checked against. Absent without a spec. */
  shipped?: ShippedChecked;
  /** Absent when there is no spec yet. */
  counts?: SpecCounts;
  /** Absent, with `risk`, when the slice has no spec yet (the engine leaves both out). */
  title?: string | null;
  risk?: RiskTier | null;
  ready: boolean;
  /** Present on `slice check`; absent on the copy inside `slice resume`. */
  status?: SliceStatus;
}

export interface SliceIds {
  next: string[];
  /** Plain IDs, or (seen on a slice made by Shape's apply) each with the feature and the slice that reserved it. */
  reserved_without_spec: Array<string | { id: string; feature: string; reserved_by: string }>;
}

export interface SlicePaths {
  work_order: string;
  specs_dir: string;
  spec: string | null;
  spec_name_pattern: string;
  intent_path: string;
}

export interface SliceNew extends SlicePaths {
  slice: WorkOrder;
  ids: SliceIds;
}

export interface SliceResume extends SlicePaths {
  slice: WorkOrder;
  resume_note: string | null;
  open_questions: string[];
  check: SliceCheck | null;
  ids: SliceIds;
  /** The builders' question, fenced as data for the interviewer; absent when there is none. */
  builders_question?: { issue: number; url: string | null; fenced: string; sha256: string; note: string };
  /** M13 A: the active principles; absent when the project has none. */
  principles?: { active: Array<Pick<Principle, "id" | "title" | "statement" | "reason" | "revision">>; note: string };
  /** M14 A: the policy packs, fenced; absent when the project has none. */
  policies?: PoliciesForInterview;
  /** M13 B: the shipped rules in force, fenced as data for the interview. */
  shipped_rules?: ShippedRulesFenced;
  /** M13 D: for a slice made from a PRD, its cited lines fenced, and its drafted answers. */
  prd?: PrdForSlice;
  /** M8 and M14 D: the request the slice was started from, fenced, with the questions its author left. */
  request?: RequestForSlice;
  /** M16: for a slice made from an idea, the outcomes it serves and the brief's earlier words, fenced. */
  idea?: SliceFromIdea;
}

export interface SlicePause {
  slice_id: string;
  saved: boolean;
  resume_with: string;
}

interface SliceReadyCommon {
  ready: true;
  slice: WorkOrder;
  /** The approved version saved. */
  revision: number;
  risk: RiskTier | null;
  counts: SpecCounts;
  warnings: string[];
  factory_authorized: false;
  note: string;
}

/** `slice ready` when the slice was saved as a GitHub issue under its epic's issue. */
export interface SliceReadyOnGithub extends SliceReadyCommon {
  saved_to: "github";
  issue: number;
  url: string;
  /** The shipped issue this one changes, when the slice had shipped before. */
  follows: number | null;
  epic_issue: number;
  project_issue: number;
  /** The GitHub account the approval was recorded for. */
  approved_by: string;
  /** M14 C: the slice's design mocks wait in the workspace for the product manager to commit them; absent without mocks. */
  mocks?: MocksToCommit | null;
}

/** `slice ready` when GitHub could not be used here: the slice was written to the ready folder. */
export interface SliceReadyInFolder extends SliceReadyCommon {
  saved_to: "folder";
  folder: string;
  files: string[];
  /** Why the folder was used, in plain words. */
  why_folder: string;
  /** The two ways the folder reaches the builders, in the engine's words. */
  ways_on: string[];
}

export type SliceReady = SliceReadyOnGithub | SliceReadyInFolder;

export interface SliceReopen {
  reopened: true;
  slice: WorkOrder;
  /** Where the slice had been saved, and what the builders had done with it. */
  github: { where: "github" | "folder" | null; issue?: number; building?: boolean; question?: boolean; shipped?: boolean };
  /** The engine's note: what reopening did and what follows, in the PM's words. */
  note: string;
  factory_authorized: false;
}

/** One epic's order (`status.order[]`, `refresh.github.order[]`, `slice move`'s `order`): the product manager's order of its slices. */
export interface OrderRow {
  epic_id: string;
  issue: number | null;
  /** In order. A slice not in this workspace is one GitHub lists under the epic. */
  slices: Array<{ slice_id: string; title: string | null; in_workspace: boolean; issue: number | null; state_label: SliceStateLabel | null }>;
  on_github: boolean;
  github_order: string[] | null;
  github_read_at: string | null;
  /** Whether GitHub holds this order; null when it does not need to or was not read. */
  matches_github: boolean | null;
  /** A move saved here and not yet in place on GitHub: moving again finishes it. */
  unfinished: boolean;
  /** Another product manager's order was taken from GitHub at the last refresh. */
  taken_from_github: boolean;
  could_not_read: boolean;
  /** What the product manager should know about this order, in the engine's words. */
  note: string | null;
}

/** `slice move`: where the slice now is. */
export interface SliceMove {
  moved: string;
  epic_id: string;
  /** 1-based. */
  position: number;
  order: OrderRow;
  github: "in_place" | "not_needed" | (string & {});
  note: string;
  factory_authorized: false;
}

/** `slice take`: a slice another product manager saved on GitHub, opened here. */
export interface SliceTake {
  taken: boolean;
  already_in_workspace: boolean;
  slice: WorkOrder;
  issue: number;
  url: string;
  note: string;
  factory_authorized: false;
}

export interface Renumber {
  renumbered: { from: string; to: string };
  changed: string[];
  needs_approval_again: string[];
  structurally_valid: boolean;
  structural_errors: string[];
}

/** `reconcile <slice> --take mine|theirs`, for a slice someone else saved a newer version of. */
export interface Reconcile {
  reconciled: string;
  took: "mine" | "theirs";
  /** The version on GitHub that was chosen against. */
  github_version: number;
  approvals_withdrawn: string[];
  note: string;
}

/* ── slice show: the spec as the validator's model ─────────────────────── */

export interface SpecSummary {
  actor: string;
  trigger: string;
  outcome: string;
}

export interface SpecStatement {
  /** INV-01, FR-01. */
  id: string;
  text: string;
}

export interface SpecRequirement extends SpecStatement {
  /** The EARS pattern: ubiquitous, event-driven, state-driven, unwanted, optional, complex. */
  pattern: string;
}

export interface MatrixRule {
  id: string;
  conditions: Record<string, string[]>;
  expected_outcome: string;
  side_effects: string;
  covers: string[];
}

export interface MatrixCase {
  id: string;
  rule: string;
  conditions: Record<string, string>;
  expected_outcome: string;
  side_effects: string;
  covers: string[];
}

export interface DecisionMatrix {
  conditions: Array<{ name: string; values: string[] }>;
  rules: MatrixRule[];
  complete: boolean;
  cases: MatrixCase[];
}

export interface Scenario {
  /** AC-01. */
  id: string;
  title: string;
  covers: string[];
  steps: Array<{ keyword: "Given" | "When" | "Then" | "And" | "But" | (string & {}); text: string }>;
}

export interface SpecModel {
  slice_id: string;
  title: string;
  summary: SpecSummary;
  in_scope: string[];
  out_of_scope: Array<{ feature: string; deferred_to: string | null }>;
  preconditions: string[];
  invariants: SpecStatement[];
  functional_requirements: SpecRequirement[];
  decision_matrix: DecisionMatrix | null;
  scenarios: Scenario[];
  external_dependencies: Array<{ name: string; failure_requirements: string[] }>;
  required_permissions: string | null;
  assumptions: string[];
  accepted_defaults: Array<{ default: string; requirements: string[] }>;
  open_questions: Array<{ question: string; follow_up: string | null }>;
  /** M13 B: the spec's effects on shipped behaviour; `[]` for "None."; absent without the section. */
  effects?: EffectRow[];
  /** M13 A: how the spec answers each principle; absent without the section. */
  principles?: PrincipleAnswer[];
  /** M14 A: how the spec answers each policy pack, with any concern; absent without the section. */
  policies?: PolicyAnswer[];
}

export interface SpecFinding {
  severity: "error" | "warning" | (string & {});
  rule: string;
  line: number | null;
  /** The spec section heading it is about; null for the whole specification. */
  section?: string | null;
  message: string;
}

export interface WhySection {
  heading: string;
  text: string;
  /** The bold `- **Name:** value` lines of the section. */
  fields: Record<string, string | undefined>;
}

/** Also called WhyDocument. */
export type WhyDocument = WhyView;

export interface WhyView {
  exists: boolean;
  markdown: string | null;
  title: string | null;
  header: Record<string, string>;
  sections: WhySection[];
}

/** `slice show`: everything the Specification Workspace needs, in one read. Changes nothing. */
export interface SliceShow {
  slice: WorkOrder;
  editable: boolean;
  /** Why the slice cannot be edited, in the engine's words (it may name a terminal command). */
  edit_refusal: string | null;
  paths: { work_order: string; specs_dir: string; spec: string | null; spec_name_pattern: string; intent: string };
  spec: {
    path: string;
    name: string;
    markdown: string;
    /** Partial when the spec has structural errors. */
    model: Partial<SpecModel>;
    findings: SpecFinding[];
  } | null;
  why: WhyView;
  check: SliceCheck;
  resume_note: string | null;
  github: SliceGithub;
  /** M15: the same field as slice.resume's, for a slice made from a PRD; read only. */
  prd?: PrdForSlice;
  /** M16: the same field as slice.resume's, for a slice made from an idea; read only. */
  idea?: SliceFromIdea;
  factory_authorized: false;
}

/* ── The operation table (contract section 3) ───────────────────────────── */

/**
 * Every operation the host exposes at POST /api/ops/<name>: its argument object (snake case, the
 * engine's own names) and its result. Keys are the contract's operation names.
 */
export interface Operations {
  where: { args: Record<string, never>; result: Where };
  status: { args: Record<string, never>; result: Status };
  validate: { args: Record<string, never>; result: Validate };
  refresh: { args: Record<string, never>; result: Refresh };
  "project.init": { args: { id: string; name: string; vision: string; outcome: string[] }; result: { project: Project; path: string } };
  "project.set": {
    args: { name?: string; vision?: string; outcome?: string[]; status?: ProjectStatus };
    result: { project: Project };
  };
  "epic.add": { args: { title: string; criterion: string[] }; result: { epic: Epic } };
  "epic.set": {
    args: { epic_id: string; title?: string; criterion?: string[]; status?: EpicStatus };
    result: { epic: Epic };
  };
  "epic.renumber": { args: { identifier: string }; result: Renumber };
  "slice.new": { args: { epic: string; title: string; depends_on?: string[]; id?: string }; result: SliceNew };
  "slice.set": { args: { slice_id: string; title?: string; epic?: string; depends_on?: string[] }; result: { slice: WorkOrder } };
  "slice.resume": { args: { slice_id?: string }; result: SliceResume };
  "slice.pause": { args: { slice_id: string; note: string }; result: SlicePause };
  "slice.check": { args: { slice_id: string; ready?: boolean }; result: SliceCheck };
  "slice.ready": { args: { slice_id: string }; result: SliceReady };
  "slice.reopen": { args: { slice_id: string }; result: SliceReopen };
  "slice.show": { args: { slice_id: string }; result: SliceShow };
  "slice.renumber": { args: { identifier: string }; result: Renumber };
  "slice.move": { args: { slice_id: string; before?: string; after?: string; first?: true; last?: true }; result: SliceMove };
  "slice.take": { args: { issue: number } | { slice_id: string }; result: SliceTake };
  reconcile: { args: { slice_id: string; take: "mine" | "theirs" }; result: Reconcile };

  /* Requests from GitHub issues (M8), promoted from features/inbox/requests/api.ts in M15. */
  "request.list": { args: Record<string, never>; result: { requests: RequestsBlock; note: string; factory_authorized?: false } };
  "request.show": { args: { number: number }; result: { request: RequestShown; note: string; factory_authorized?: false } };
  "request.pick": { args: { number: number; epic: string; title: string; also?: boolean }; result: RequestPickResult };
  "request.link": { args: { number: number; slice_id: string }; result: { linked: true; request: number; note: string } };
  "request.met": { args: { number: number }; result: { met: true; request: number; approved_slices: string[]; closed: boolean; note: string } };

  /* M15: what M13 and M14 added. Argument shapes are the host's (apps/studio/internal/engine/ops_product.go). */
  "principle.list": { args: Record<string, never>; result: PrincipleList };
  "principle.add": { args: { title: string; statement: string; reason: string }; result: PrincipleChanged };
  "principle.set": { args: { principle_id: string; title?: string; statement?: string; reason?: string }; result: PrincipleChanged };
  "principle.retire": { args: { principle_id: string }; result: PrincipleChanged };
  "principle.publish": { args: Record<string, never>; result: PrinciplesPublishResult };
  "reconcile.principles": { args: { take: "mine" | "theirs" }; result: ReconcilePrinciples };
  "policy.list": { args: Record<string, never>; result: PolicyList };
  "policy.accept": { args: { slice_id: string; policy_id: string; by: string; reason: string }; result: PolicyAccept };
  "epic.current": { args: { epic_id: string } | { issue: number }; result: EpicCurrent };
  "epic.link": { args: { epic_id: string; jira: string } | { epic_id: string; remove: true }; result: EpicLink };
  "slice.link": { args: { slice_id: string; jira: string } | { slice_id: string; remove: true }; result: SliceLink };
  "jira.export": { args: { epic?: string; state?: "ready" | "all"; flavour?: "cloud" | "data-center" }; result: JiraExport };
  "jira.keys": { args: { file: UploadFile; dry_run?: boolean }; result: JiraKeys };
  "prd.import": { args: { file: UploadFile }; result: PrdImport };
  "prd.list": { args: Record<string, never>; result: { prds: PrdSummary[]; factory_authorized: false } };
  "prd.show": { args: { prd_id: string; lines?: string }; result: PrdShow };
  "prd.map": { args: { prd_id: string; map: PrdMapInput }; result: PrdStatus & { recorded: true; settlements_dropped: number[] } };
  "prd.settle": {
    args: { prd_id: string; section: number; as: "slice"; slice: string; reason?: string } | { prd_id: string; section: number; as: "out-of-scope" | "later"; reason?: string };
    result: PrdStatus & { settled: { section: number } & PrdSettlement };
  };
  "prd.status": { args: { prd_id: string }; result: PrdStatus };
  "prd.apply": { args: { prd_id: string }; result: PrdApply };
  "prd.draft": { args: { slice_id: string; answers: PrdAnswersInput }; result: PrdAnswersResult & { recorded: true; cleared_earlier_confirmations: boolean } };
  "prd.confirm": { args: { slice_id: string; accept?: "all" | number[]; discuss?: number[] }; result: PrdAnswersResult & { confirmed: true } };
  "slice.mock.add": { args: { slice_id: string; file: UploadFile; for?: string; binding?: boolean; note?: string }; result: MockAdd };
  "slice.mock.remove": { args: { slice_id: string; mock: string }; result: MockRemove };
  "slice.mock.list": { args: { slice_id: string }; result: MockList };

  /* M16: Shape. Argument shapes are the host's (apps/studio/internal/engine/ops_shape.go). */
  "idea.add": { args: { title: string; from_request?: number; from_issue?: number; from_fault?: string }; result: IdeaAdded };
  "idea.list": { args: Record<string, never>; result: IdeaBoard & { factory_authorized: false } };
  "idea.faults": { args: Record<string, never>; result: IdeaFaults };
  "idea.show": { args: { idea_id: string }; result: IdeaShow };
  "idea.stage": { args: { idea_id: string; stage: "exploring" }; result: IdeaStageResult };
  "idea.lookups": { args: { idea_id: string; lookups: IdeaLookupsInput }; result: IdeaLookupsResult };
  "idea.renumber": { args: { idea_id: string }; result: IdeaRenumbered };
  "idea.publish": { args: { idea_id: string }; result: IdeaPublished };
  "idea.size": { args: { idea_id: string }; result: IdeaSized };
  "idea.map": { args: { idea_id: string; map: ShapeMapInput }; result: ShapeMapRecorded };
  "idea.settle": {
    args:
      | { idea_id: string; outcome: string; as: "slice"; slice: string; reason?: string }
      | { idea_id: string; outcome: string; as: "out-of-scope" | "later"; reason: string };
    result: ShapeSettled;
  };
  "idea.map-status": { args: { idea_id: string }; result: ShapeMapStatus };
  /** `change`: for the small-change route only (M18), the product manager's word on which kind it is. */
  "idea.apply": { args: { idea_id: string; change?: "fix" | "adjustment" }; result: ShapeApplied };
  "idea.change": { args: { rule: string; title?: string }; result: IdeaChanged };
  "idea.chain": { args: { idea_id: string }; result: IdeaChain };
  "brief.check": { args: { idea_id: string }; result: BriefCheck };
  "brief.show": { args: { idea_id: string }; result: BriefShow };
  "case.show": { args: { idea_id: string }; result: CaseShow };
  "case.check": { args: { idea_id: string }; result: CaseCheck };
  "verdict.record": { args: { idea_id: string; decision: "go" | "not-now" | "no"; reason: string }; result: VerdictRecorded };
  "lookback.record": {
    args:
      | { idea_id: string; outcome: string; result: "met" | "not-met" | "too-early"; note: string }
      | { idea_id: string; assumption: string; result: "confirmed" | "wrong" | "unknown"; note: string };
    result: LookbackRecorded;
  };

  /* M17: technical needs and a design the team already has. Argument shapes are the host's (apps/studio/internal/engine/ops_needs.go).
     `design map` is not an operation: the needs conversation records a design's map. */
  "need.list": { args: Record<string, never>; result: NeedList };
  "need.add": {
    args:
      | { kind: Exclude<NeedKind, "given">; statement: string; why: string }
      | { kind: "given"; statement: string; why: string; said_by: string; said_on: string };
    result: NeedChanged;
  };
  "need.set": { args: { need_id: string; statement?: string; why?: string; said_by?: string; said_on?: string }; result: NeedChanged };
  "need.retire": { args: { need_id: string }; result: NeedChanged };
  "need.none": { args: { kind: NeedKind }; result: NeedNothingToSay };
  "need.publish": { args: Record<string, never>; result: NeedsPublishResult };
  "reconcile.needs": { args: { take: "mine" | "theirs" }; result: ReconcileNeeds };
  "design.list": { args: Record<string, never>; result: { designs: DesignSummary[]; factory_authorized: false } };
  "design.import": { args: { file: UploadFile }; result: DesignImport };
  "design.show": { args: { design_id: string; lines?: string }; result: DesignShow };
  "design.settle": { args: { design_id: string; conflict: number; as: DesignSettleAs; reason: string; by?: string }; result: DesignSettled };
  "design.publish": { args: { design_id: string }; result: DesignPublished };
}

export type OperationName = keyof Operations;
export type OperationArgs<K extends OperationName> = Operations[K]["args"];
export type OperationResult<K extends OperationName> = Operations[K]["result"];

/**
 * Operations that change nothing in the workspace. Every other operation, and every draft write,
 * may change what `status` reports, so the client announces it (MachClient.onChange).
 */
export const readOnlyOperations: ReadonlySet<OperationName> = new Set<OperationName>([
  "where",
  "status",
  "validate",
  "slice.show",
  "request.list",
  "request.show",
  "principle.list",
  "policy.list",
  "epic.current",
  "prd.list",
  "prd.show",
  "prd.status",
  "slice.mock.list",
  "idea.list",
  "idea.faults",
  "idea.show",
  "idea.map-status",
  "idea.chain",
  "brief.show",
  "case.show",
  "case.check",
  "need.list",
  "design.list",
  "design.show",
]);

/**
 * Operations that record a person's decision. The UI confirms each in a dialog before calling it,
 * as "Mark ready to build" is confirmed. The engine does each only "on the product manager's word"
 * (or, for policy.accept, on the policy owner's), and the guided interview can run none of them.
 */
export const personalActs: ReadonlySet<OperationName> = new Set<OperationName>([
  "slice.ready",
  "slice.reopen",
  "reconcile",
  "slice.renumber",
  "epic.renumber",
  "slice.take",
  "request.pick",
  "request.link",
  "request.met",
  "principle.add",
  "principle.set",
  "principle.retire",
  "principle.publish",
  "reconcile.principles",
  "policy.accept",
  "epic.link",
  "slice.link",
  "jira.export",
  "jira.keys",
  "prd.settle",
  "prd.apply",
  "prd.confirm",
  "slice.mock.add",
  "slice.mock.remove",
  // M16: Shape's acts on the product manager's word (references/shape.md rule 6).
  "verdict.record",
  "idea.publish",
  "idea.renumber",
  "idea.settle",
  "idea.apply",
  "idea.change",
  "lookback.record",
  // M17: the product manager's acts on the technical needs and a brought-in design (references/needs.md and design.md).
  // need.add, need.set and need.none are also what the needs conversation records with the PM's words; on the page
  // they are the PM's own buttons. Nothing here accepts an ADR.
  "need.add",
  "need.set",
  "need.retire",
  "need.none",
  "need.publish",
  "reconcile.needs",
  "design.import",
  "design.settle",
  "design.publish",
]);

/* ── M15: types for what M13 and M14 added (web/fixtures/product_memory.py holds real samples) ── */

/** A file the person chose, sent inside the JSON body. Build it with `uploadFile()` from @mach/ui/api. */
export interface UploadFile {
  /** The file's own name; the host keeps only a plain base name and its extension. */
  name: string;
  content_base64: string;
}

/** The host's limits, which it enforces before the engine sees anything (ops_product.go). */
export const uploadLimits = {
  prd: { maxBytes: 512 * 1024, extensions: [".md", ".markdown", ".txt", ".text"] },
  mock: { maxBytes: 5 * 1024 * 1024, extensions: [".png", ".jpg", ".jpeg"] },
  jiraKeys: { maxBytes: 8 * 1024 * 1024, extensions: [".csv"] },
  /** A PRD map or a set of drafted answers, as JSON. */
  json: { maxBytes: 1024 * 1024 },
  /** M16: an idea's lookups or its map, as JSON (the engine's own limit). */
  shapeJson: { maxBytes: 256 * 1024 },
  /** M17: a design document; the PRD on-ramp's own limits (design.py shares prd.Imported). */
  design: { maxBytes: 512 * 1024, extensions: [".md", ".markdown", ".txt", ".text"] },
} as const;

export interface Tracking {
  /** A Jira key such as ABC-123. */
  jira: string;
}

/* Principles (M13 A) */

export interface Principle {
  /** PP-01. */
  id: string;
  title: string;
  /** One sentence with MUST, MUST NOT, SHALL, SHALL NOT or REQUIRED. Shown lowered for reading. */
  statement: string;
  reason: string;
  status: "active" | "retired";
  /** Counts changes to the statement; every spec quotes it with its revision. */
  revision: number;
}

/** Where the principles are published and what GitHub held at the last read. */
export interface PrinciplesPublished {
  saved: "github" | "folder" | null;
  unfinished: boolean;
  /** The published version (of the set). */
  revision: number | null;
  sha256: string | null;
  approved_by: string | null;
  published_at: string | null;
  issue: number | null;
  url: string | null;
  github: { revision: number | null; approved: boolean | null; approved_by: string | null; read_at: string | null } | null;
  /** Someone else published a newer version: choose with reconcile.principles. */
  newer_elsewhere: boolean;
  changed_on_github: boolean;
}

/** `status.principles`, and the same fields in `principle.list`. */
export interface PrinciplesBlock {
  active: string[];
  retired: string[];
  unpublished_changes: boolean;
  published: PrinciplesPublished;
  /** Slices answered under an older revision of a principle, or leaving an active one unanswered. */
  slices_answered_under_older: string[];
  /** The one sentence to show about what to do next, or null. */
  next: string | null;
}

export interface PrincipleList extends PrinciplesBlock {
  principles: Principle[];
  note: string;
  factory_authorized: false;
}

/** Per slice in status: how its spec answers the principles now. */
export interface SlicePrinciplesFlag {
  answered_under_older: boolean;
  older: string[];
  unanswered: string[];
  retired: string[];
  note: string | null;
}

export interface PrincipleChanged {
  principle: Principle;
  /** The statement check's warnings, in the engine's words. Absent for retire. */
  warnings?: string[];
  published: false;
  factory_authorized: false;
  note: string;
}

export type PrinciplesPublishResult =
  | { published: true; saved_to: "github"; revision: number; sha256: string; issue: number; url: string; approved_by: string; active: number; factory_authorized: false; note: string }
  | {
      published: true;
      saved_to: "folder";
      revision: number;
      sha256: string;
      folder: string;
      /** Why the folder was used rather than GitHub, in the engine's words. */
      why_folder: string;
      files: string[];
      ways_on: string[];
      active: number;
      factory_authorized: false;
      note: string;
    };

export interface ReconcilePrinciples {
  reconciled: "principles";
  took: "mine" | "theirs";
  github_version: number;
  note: string;
  factory_authorized: false;
}

/** A spec's `## Principles` row, as the validator exports it. */
export interface PrincipleAnswer {
  id: string;
  revision: number;
  statement: string;
  answer: "applies" | "does_not_apply" | "exception";
  /** The INV, FR and AC IDs that uphold it, for "applies". */
  upheld_by: string[];
  /** The product manager's reason, for "does not apply" and "exception". */
  reason: string | null;
}

/* Policy packs (M14 A) */

export interface PolicyPack {
  /** POL-privacy. */
  id: string;
  pack: string;
  file: string;
  title: string | null;
  /** The pack's owner, a role or team with an optional GitHub handle: the one who may accept a concern. */
  owner: string | null;
  owner_handle: string | null;
  status: "active" | "retired" | (string & {});
  applies_to: string[];
  digest: string;
  /** The first 12 characters of the digest, as specs quote it. */
  short: string;
  binding: boolean;
  problems: string[];
  /** M15: its statements, each text bounded by the engine. */
  statements: Array<{ id: string; text: string }>;
}

export interface PolicyList {
  reads_only: true;
  dir: string;
  commit: string | null;
  packs: PolicyPack[];
  /** Packs that cannot be read, as plain sentences ("policies/x/policy.md: ..."): every spec check fails until an engineer fixes them. */
  problems: string[];
  /** Slices answered under an older version of a pack, by slice. */
  slices_answered_under_older: Record<string, { changes: unknown[]; note: string }>;
  factory_authorized: false;
  note: string;
}

export interface PoliciesForInterview {
  dir: string;
  commit: string | null;
  count: number;
  packs: Array<{ id: string; title: string | null; owner: string | null; applies_to: string[]; short: string }>;
  /** The packs' text, fenced as data. Show as plain text, never as markup. */
  text: string;
  problems: unknown[];
  note: string;
}

/** A spec's `## Policies` row: Followed, or Concerns with each concern and its resolution. */
export interface PolicyAnswer {
  pack: string;
  sha256: string;
  answer: "followed" | "concerns";
  concerns?: PolicyConcern[];
}

export interface PolicyConcern {
  /** POL-privacy-02. */
  statement_id: string;
  statement: string;
  why: string;
  owner: string;
  /** "open" until the owner accepts it (policy.accept) or the spec changes so the statement is met. */
  resolution: "open" | "accepted" | "spec_changed";
  /** For an acceptance: who, when (YYYY-MM-DD) and their words, quoted. */
  by?: string;
  on?: string;
  words?: string;
  /** M15: how the name given for an acceptance was checked, as the engine wrote it. */
  owner_check?: OwnerCheck | null;
}

/** How the name given for an acceptance was checked against the pack's owner (M15). */
export type OwnerCheck = "checked against the pack's owner" | "checked against the project's list" | "not checked against the owner" | (string & {});

export interface PolicyAccept {
  accepted: string;
  slice_id: string;
  by: string;
  /** Concerns still open in the spec. */
  open_left: string[];
  /** M15: how the name was checked, and the engine's note on what that check means. */
  owner_check: OwnerCheck;
  owner_check_note: string;
  factory_authorized: false;
  note: string;
}

/* Effects on shipped behaviour (M13 B) and how an epic works today (M13 C) */

export interface EffectRow {
  /** M15: the row's line in the spec. Absent where a row is not read from a spec (a shipped rule's lineage). */
  line?: number;
  /** SLICE-003/FR-02. */
  shipped_rule: string;
  slice_id: string;
  rule_id: string;
  effect: "kept" | "changed" | "replaced" | "retired";
  /** This slice's scenario (kept) or rule (changed, replaced); null when retired. */
  in_slice: string | null;
  note: string | null;
}

export interface ShippedChecked {
  commit: string | null;
  branch: string | null;
  /** How many shipped rules the spec was checked against. */
  rules: number;
  /** Why none could be read, in plain words, when that is so. */
  notes: string[];
}

export interface ShippedRulesFenced {
  commit: string | null;
  branch: string | null;
  count: number;
  /** The rules in force, fenced as data: show as plain text. */
  fenced: string;
  sha256: string;
  notes: string[];
  note: string;
  cut?: boolean;
}

export interface ShippedMoved {
  /** The commit the spec was checked at, and the one it is compared with now. */
  checked_at: string;
  now: string;
  problems: Array<{ line: number | null; code: "effects-not-in-force" | "effects-not-shipped" | (string & {}); message: string }>;
  note: string;
}

export interface ShippedRule {
  /** SLICE-001/FR-01. */
  rule: string;
  slice_id: string;
  id: string;
  kind: "invariant" | "requirement" | "decision rule" | "scenario" | (string & {});
  text: string;
  epic_id: string | null;
  confirmed_by?: Array<{ slice_id: string; scenario: string; note: string | null }>;
  takes_the_place_of?: Array<{ effect: EffectRow["effect"]; rule: string; epic_id: string | null; note: string | null }>;
  lineage?: unknown[];
  /** For a rule no longer in force: what replaced or retired it, and what holds now. */
  superseded_by?: Array<{ effect: EffectRow["effect"]; by: string | null; slice_id: string; epic_id: string | null; note: string | null }>;
  now?: Array<{ rule: string; slice_id: string; epic_id: string | null; text: string }>;
}

export interface EpicView {
  epic_id: string;
  title: string | null;
  issue: number | null;
  slices: Array<{ slice_id: string; title: string | null; issue: number | null; path: string; effects: "declared" | "none" | "missing" | (string & {}); notes: string[] }>;
  in_force: ShippedRule[];
  /** Shipped before slices declared their effects, so not reconciled: shown, with that said. */
  not_yet_reconciled: ShippedRule[];
  no_longer_in_force: ShippedRule[];
  /** Slices whose effects have problems, so none of them was applied, with each problem. */
  not_applied: Array<{ slice_id: string; problems: Array<{ line: number; code: string; message: string }> }>;
  /** Two shipped slices that change the same rule, in plain sentences. */
  conflicts: string[];
}

/** `epic current`: the epic as merged on this machine's copy of the integration branch. Changes nothing. */
export interface EpicCurrent {
  epic_id: string | null;
  branch: string;
  commit: string;
  /** Says the view may be behind GitHub and that the slices are the authority. Always show it. */
  note: string;
  /** Null when no shipped slice names the epic. */
  epic: EpicView | null;
  notes: string[];
  factory_authorized: false;
}

/* The Jira key, export and keys back (M13 E) */

export interface EpicLink {
  epic: Epic;
  /** Slices already marked ready that carry the new key only once each is reopened and marked ready again. */
  already_ready: string[];
  factory_authorized: false;
  note: string;
}

export interface SliceLink {
  slice: WorkOrder;
  /** The key the slice is handed over with: its own, else its epic's; null when none. */
  jira: string | null;
  factory_authorized: false;
  note: string;
}

/** One file the host offers after an export: `url` is `/api/downloads/<token>/<name>`, valid until the next export. */
export interface DownloadOffer {
  name: "mach-jira.csv" | "README.txt" | (string & {});
  url: string;
  bytes: number;
}

export interface JiraExport {
  /** Where the engine wrote, on this computer. The app offers `downloads` instead of showing these. */
  folder: string;
  file: string;
  readme: string;
  flavour: "cloud" | "data-center";
  state: "ready" | "all";
  epic: string | null;
  counts: { epics: number; stories: number };
  /** The MACH IDs in the file. */
  exported: string[];
  left_out: Array<{ id: string; reason: string; jira?: string }>;
  cut: string[];
  factory_authorized: false;
  note: string;
  /** Added by the host, never by the engine. */
  downloads: DownloadOffer[];
}

export interface JiraKeys {
  dry_run: boolean;
  rows_read: number;
  linked: Array<{ id: string; jira: string }>;
  already_linked: Array<{ id: string; jira: string }>;
  needs_reopening: Array<{ id: string; jira: string; reason: string }>;
  /** Rows that name no MACH item, or several, or one this workspace does not have. */
  unmatched: Array<{ row?: number; rows?: number[]; id?: string; reason: string }>;
  refused: Array<{ row?: number; rows?: number[]; id?: string; reason: string }>;
  epics_with_ready_slices: Record<string, string[]>;
  factory_authorized: false;
  note: string;
}

/* The PRD on-ramp (M13 D) */

export interface PrdSource {
  kind: "prd";
  prd_id: string;
  sha256: string;
  lines: Array<[number, number]>;
  map_slice: string;
}

export interface PrdSummary {
  prd_id: string;
  /** The document's file name as imported. */
  name: string;
  format: "markdown" | "text";
  sha256: string;
  line_count: number;
  sections: number;
  /** False when the copy in the workspace no longer matches what was imported. */
  document_matches: boolean;
  mapped: boolean;
  slices_mapped?: number;
  not_covered?: number[];
  applied?: string[];
}

export interface PrdSection {
  n: number;
  title: string;
  level: number;
  start: number;
  end: number;
  /** A heading with nothing under it: needs no coverage. */
  heading_only: boolean;
}

export interface PrdImport {
  imported: boolean;
  already_imported?: true;
  prd: PrdSummary;
  sections?: PrdSection[];
  factory_authorized: false;
  note: string;
}

export interface PrdShow {
  prd: PrdSummary;
  sections: PrdSection[];
  /** The numbered text, fenced as data, bounded and redacted. Show as plain text. */
  fenced: string;
  sha256: string;
  lines: string;
  truncated: boolean;
  note: string;
  factory_authorized: false;
}

export interface PrdSettlement {
  as: "slice" | "out-of-scope" | "later";
  slice?: string;
  at: string;
  reason?: string;
}

export interface PrdCoverageRow {
  n: number;
  title: string;
  lines: string;
  cited_by: string[];
  state: "covered" | "not_covered" | "settled" | "heading_only";
  settled?: PrdSettlement;
}

export interface PrdMapSlice {
  key: string;
  title: string;
  scope: string;
  /** A new epic's key before apply, its EPIC ID after. */
  epic: string;
  depends_on: string[];
  cites: string;
  lines: string;
  slice_id: string | null;
  status?: SliceStatus;
  answers?: { pending: number[]; accepted: number[]; discuss: number[] } | null;
}

export interface PrdStatus {
  prd: PrdSummary;
  factory_authorized: false;
  /** Null before a map is recorded; then `sections` lists the sections. */
  map: { revision: number; epics: Array<{ key: string; title: string; criteria: string[] }>; slices: PrdMapSlice[]; applied: boolean } | null;
  sections?: Array<{ n: number; title: string; lines: string }>;
  coverage?: PrdCoverageRow[];
  /** Sections no slice cites and the product manager has not settled. */
  not_covered?: number[];
  can_apply?: boolean;
  note: string;
}

export interface PrdApply extends PrdStatus {
  applied: true;
  made: { epics: string[]; slices: string[] };
  kept: { epics: string[]; slices: string[] };
  missing: string[];
}

/** The map `prd.map` records, as the planning model proposes it (skills/product-studio/references/prd-onramp.md). */
export interface PrdMapInput {
  epics: Array<{ key: string; title: string; criteria: string[] }>;
  slices: Array<{ key: string; title: string; scope: string; epic: string; depends_on: string[]; cites: string[] }>;
}

/** Answers drafted from a slice's cited lines, as `prd.draft` records them. */
export interface PrdAnswersInput {
  answers: Array<{ question: string; answer?: string; kind?: "drafted" | "not_settled" | "contradiction"; cites?: string[] }>;
}

export interface PrdAnswer {
  n: number;
  kind: "drafted" | "not_settled" | "contradiction";
  kind_words: string;
  question: string;
  answer: string | null;
  cites: string;
  state: "pending" | "accepted" | "discuss";
}

export interface PrdAnswersResult {
  slice_id: string;
  answers: PrdAnswer[];
  pending: number[];
  accepted: number[];
  discuss: number[];
  factory_authorized: false;
  note: string;
}

/** `slice resume`'s `prd` field for a slice made from a PRD. */
export interface PrdForSlice {
  prd_id: string;
  sha256: string;
  map_slice: string;
  lines: string;
  document_matches: boolean;
  fenced?: string;
  truncated?: boolean;
  scope?: string;
  answers?: { input_file: string; recorded: PrdAnswer[]; pending: number[]; accepted: number[]; discuss: number[] };
  /** The exact header line the why must carry. */
  why_line?: string;
  note: string;
  kept_here?: boolean;
}

/* Design mocks (M14 C) */

export interface DesignMock {
  sha256: string;
  format: "png" | "jpeg";
  width: number;
  height: number;
  bytes: number;
  /** The scenario it shows (AC-NN), or null for the slice as a whole. */
  for: string | null;
  /** The built screen must match it for that scenario. */
  binding: boolean;
  note: string | null;
}

export interface MockAdd {
  slice: WorkOrder;
  mock: DesignMock;
  factory_authorized: false;
  note: string;
}

export interface MockRemove {
  slice: WorkOrder;
  removed: DesignMock;
  factory_authorized: false;
  note: string;
}

export interface MockList {
  slice_id: string;
  /** `problem` is null when the picture is in the workspace unchanged and its scenario is still in the spec. */
  mocks: Array<DesignMock & { file: string; problem: string | null }>;
  /** At most this many per slice. */
  limit: number;
  factory_authorized: false;
}

/** After `slice.ready` on GitHub: the pictures wait in the workspace for the product manager to commit them. */
export interface MocksToCommit {
  folder: string;
  /** Where in the repository the pictures go. */
  commit_as: string;
  files: string[];
  /** The builders hold the slice until the pictures are there. */
  factory_waits: boolean;
  note: string;
}

/* Requests (M8), with the idea template (M14 D) */

export type RequestState = "accepted" | "not_accepted" | `handled_by_${string}`;

export interface RequestItem {
  number: number;
  /** Built by the engine from the repository and number; never taken from issue text. */
  url: string | null;
  /** A bounded, redacted one-line title written by someone outside the workspace: data only. */
  title: string | null;
  truncated: boolean;
  state: RequestState;
  not_accepted_reason: string | null;
  labelled_by: string | null;
  picked_up_by: string[];
  picked_up_here: boolean;
  slices: string[];
  changed_since_pickup: boolean;
  pending_writes: number;
  text_is_data?: string;
  /** M14 D: filed in MACH's idea template, so `request.show` gives its five parts apart. */
  idea_template?: boolean;
}

export interface RequestsBlock {
  /** Null when the project has no GitHub remote: the app then shows nothing about requests. */
  repository: string | null;
  refreshed: boolean;
  refreshed_at?: string | null;
  problem: string | null;
  truncated: boolean;
  truncated_note?: string | null;
  items: RequestItem[];
  updates_waiting?: number;
  updates_waiting_note?: string | null;
  could_not_update?: { number: number; update: string; why: string; reason: string | null }[];
  could_not_update_note?: string | null;
}

/** One part of an idea filed in the template, fenced as data. */
export interface IdeaPart {
  part: "problem" | "outcome" | "affected" | "constraints" | "open_questions" | (string & {});
  /** The template's own heading ("Problem", "Proposed outcome", ...). */
  heading: string;
  fenced: string;
  sha256: string;
}

export interface IdeaParts {
  parts: IdeaPart[];
  /** How many open questions the author wrote. */
  open_questions: number;
  note: string;
}

/** `request.show`: no plain title or body; the text only fenced, and none for a request that does not count. */
export type RequestShown = Omit<RequestItem, "title"> & {
  fenced?: string;
  sha256?: string;
  text_shown: boolean;
  text_note?: string;
  /** M14 D: present only for a request filed in the idea template. */
  idea?: IdeaParts;
};

/** The open questions the author of an idea left, fenced, to ask first in the interview. */
export interface QuestionsToAskFirst {
  count: number;
  fenced: string;
  sha256: string;
  note: string;
}

/** The request a slice was started from, as `request.pick` and `slice resume` carry it. */
export interface RequestForSlice {
  number: number;
  repository: string;
  url: string | null;
  kept_here: boolean;
  fenced?: string;
  sha256?: string;
  changed_since_pickup: boolean;
  note: string;
  /** M14 D: present only for a request filed in the idea template. */
  questions_to_ask_first?: QuestionsToAskFirst;
}

export interface RequestPickResult {
  slice: WorkOrder;
  picked: true;
  request?: RequestForSlice;
  github_updates?: { made?: number; waiting?: number; note: string | null } | null;
  used_cached_request?: string | null;
  note: string;
  factory_authorized?: false;
}

/* ── Host endpoints (contract section 4) ────────────────────────────────── */

/** GET /api/session (contract 8.1). Needs the session cookie; never needs the CSRF token. */
export interface Session {
  project: {
    /** The project folder's name. */
    folder: string;
    /** The project's absolute path on this machine. */
    path: string;
    /** From the engine's status; null before `project init`. */
    name: string | null;
    project_id: string | null;
  };
  csrf_token: string;
  capabilities: {
    interview: boolean;
    /** Why the interview is unavailable, in plain words; null when it is available. */
    interview_reason: string | null;
    /**
     * The command prefix for continuing in Claude Code ("/mach:product-studio continue" for a plugin
     * install); the app appends the slice ID. Null when the host does not say.
     */
    continue_command?: string | null;
    /** M16: the same install's command that explores an idea, without the idea ID ("/mach:product-studio explore"). */
    explore_command?: string | null;
    /** M17: the same install's command that talks through the technical needs ("/mach:product-studio needs"). */
    needs_command?: string | null;
  };
  versions: { host: string; api: string | number; engine_install: string | null };
  /** Set when the engine could not report status while building the session. */
  engine_problem: { kind: string; message: string } | null;
}

/** GET /api/drafts/{spec|intent}/<slice>. */
export interface DraftRead {
  slice_id: string;
  kind: "spec" | "intent";
  editable: boolean;
  edit_refusal: string | null;
  path: string | null;
  exists: boolean;
  markdown: string | null;
  /** Spec only. */
  spec_name_pattern?: string;
}

/** PUT /api/drafts/{spec|intent}/<slice> returns where it wrote and the check that followed. */
export interface DraftWriteResult {
  slice_id: string;
  kind: "spec" | "intent";
  path: string;
  check: SliceCheck;
}

/* ── The interview (contract 8.2) ──────────────────────────────────────── */

export type InterviewHostState = "starting" | "thinking" | "working" | "waiting_for_reply" | "ended" | "failed";
/** Kept for the first wave's name. */
export type InterviewState = InterviewHostState;

export type MessageKind = "question" | "confirmation" | "other";

export interface ParsedQuestion {
  message_id: string;
  /** Restarts at 1 in every session: never a key. */
  number: number;
  title: string;
  body: string;
  recommendation: string;
  /** Up to a few lines the interviewer wrote before the question. */
  preface: string;
}

export type ActivityKind = "lookup" | "check" | "save" | "write" | "refused" | "other";

export type TurnOutcome = "replied" | "interrupted" | "timed_out" | "failed" | "error_max_budget_usd" | (string & {});

export type InterviewErrorKind =
  | "no_result"
  | "timed_out"
  | "error_max_budget_usd"
  | "error_during_execution"
  | "unavailable"
  | (string & {});

export interface InterviewEventMap {
  state: InterviewHostState;
  /** A streamed chunk; may belong to a message that never becomes final. */
  text: { message_id: string; delta: string };
  /** Once per turn: the reply the PM answers. */
  message: { message_id: string; text: string; kind: MessageKind };
  /** Sent with `message` when it parses as exactly one question. Key by message_id. */
  question: ParsedQuestion;
  activity: { kind: ActivityKind; text: string };
  /**
   * A slice's interview names `slice_id`; the Shape conversation (M16) names `idea_id`, with brief, case, lookups or idea;
   * the needs conversation (M17) says `needs: true`, with needs (product/needs.json) or design (a design's map).
   */
  draft_changed: {
    slice_id?: string;
    idea_id?: string;
    needs?: true;
    what: Array<"spec" | "why" | "work_order" | "brief" | "case" | "lookups" | "idea" | "needs" | "design" | (string & {})>;
  };
  turn: { outcome: TurnOutcome; seconds: number; cost_usd: number | null; session_cost_usd: number | null; refused: number | string[] | null };
  /** The product manager's own reply, first in the turn it starts. */
  reply: { text: string };
  ended: { reason: "stopped" | "failed" | "host_shutdown" | (string & {}) };
  error: { kind: InterviewErrorKind; message: string };
}

export type InterviewEventName = keyof InterviewEventMap;
/** Kept for the first wave's name. */
export type InterviewEventType = InterviewEventName;

/**
 * One event from GET /api/interview/<id>/events. `seq` is the SSE `id` (the host's sequence number),
 * or null when the host sent none; the client drops events it has already seen.
 */
export type InterviewEvent = { [K in InterviewEventName]: { type: K; data: InterviewEventMap[K]; seq: number | null } }[InterviewEventName];

export const interviewEventNames: InterviewEventName[] = ["state", "text", "message", "question", "activity", "draft_changed", "turn", "reply", "ended", "error"];
/** Kept for the first wave's name. */
export const interviewEventTypes: readonly InterviewEventName[] = interviewEventNames;

/** GET /api/interview?slice_id=: what the host knows about a slice's interview. */
export interface InterviewSummary {
  interview_id: string | null;
  /** The slice's interview; absent for the Shape conversation (M16), which names `idea_id`. */
  slice_id?: string;
  idea_id?: string;
  /** M17: the needs conversation (one per project). */
  needs?: true;
  /** A process holds this slice's interview now. False when only a saved session exists. */
  live: boolean;
  state: InterviewHostState | "saved";
  turn_running: boolean;
  /** Another host or window holds the slice's lock. */
  locked_elsewhere: boolean;
  last_message: { message_id: string; text: string; kind: MessageKind; question: ParsedQuestion | null } | null;
  turns: number;
  session_cost_usd: number | null;
}

/** GET /api/interview/history?slice_id=: every saved event, oldest first, across interviews and restarts. */
export interface InterviewHistory {
  slice_id?: string;
  /** M16: the Shape conversation's history. */
  idea_id?: string;
  /** M17: the needs conversation's history. */
  needs?: true;
  events: Array<{ at: string; interview_id: string; event: InterviewEventName; data: unknown }>;
  /** The oldest events were dropped to keep the history small. */
  truncated: boolean;
}

/** POST /api/interview. */
export interface StartResult {
  interview_id: string;
  slice_id?: string;
  /** M16: the Shape conversation started for this idea. */
  idea_id?: string;
  /** M17: the needs conversation started. */
  needs?: true;
  resumed: boolean;
}

/* ── Fixture file shape ─────────────────────────────────────────────────── */

/** Widens string and boolean literals so a JSON import can be checked against an engine type. */
export type LooseJson<T> = T extends string
  ? string
  : T extends boolean
    ? boolean
    : T extends ReadonlyArray<infer U>
      ? LooseJson<U>[]
      : T extends object
        ? { [K in keyof T]: LooseJson<T[K]> }
        : T;

/** How web/fixtures/*.json store one engine run. */
export interface EngineRun<T> {
  exit_code: number;
  data: T | null;
  /** The engine's refusal message (stderr after "refused: "), or null. */
  refused: string | null;
  /** The refusal's structured suggestion, when the engine gave one. */
  hint?: ErrorHint | null;
}
